"""Compares the OpenAPI generated by FastAPI with the contract in docs/api/openapi.yaml.

Every operation the app serves must exist in the contract with the same operationId,
parameters, request body and response schemas. Contract operations that are not
implemented yet are skipped here; test_openapi_drift checks them against pending.py.
Schemas are compared by structure (types, enums, formats, properties, required
fields); titles, descriptions and constraints are not.
"""

from typing import Any

API_PREFIX = "/api/v1"
HTTP_METHODS = ("get", "put", "post", "delete", "patch")

# Values the backend emits that are not in the contract yet (questions.md, B-01).
PENDING_ENUM_VALUES = {"method_not_allowed"}

Schema = dict[str, Any]


def _resolve(spec: Schema, node: Any) -> Any:
    while isinstance(node, dict) and "$ref" in node:
        target: Any = spec
        for part in node["$ref"].removeprefix("#/").split("/"):
            target = target[part]
        node = target
    return node


def _types(schema: Schema) -> set[str]:
    declared = schema.get("type")
    if declared is None:
        return set()
    return {declared} if isinstance(declared, str) else set(declared)


def _merge_all_of(spec: Schema, schema: Schema) -> Schema:
    """Flattens `allOf` (the contract's `*Page` = PageMeta + items) into one object."""
    merged: Schema = {"type": "object", "properties": {}, "required": []}
    for part in [_normalize(spec, part) for part in schema.pop("allOf")] + [schema]:
        merged["properties"].update(part.get("properties", {}))
        merged["required"] += part.get("required", [])
    return merged


def _normalize(spec: Schema, schema: Any) -> Schema:
    """Resolves refs, flattens `allOf`, folds `anyOf: [X, {type: null}]` into `type: [X, null]`."""
    schema = dict(_resolve(spec, schema) or {})
    if len(schema.get("allOf", [])) > 1:
        return _merge_all_of(spec, schema)
    variants = schema.pop("anyOf", None) or schema.pop("oneOf", None)
    if variants is None and len(schema.get("allOf", [])) == 1:
        variants = schema.pop("allOf")
    if variants:
        resolved = [_resolve(spec, variant) for variant in variants]
        non_null = [variant for variant in resolved if _types(variant) != {"null"}]
        if len(non_null) != 1:
            return {"anyOf": [_normalize(spec, variant) for variant in resolved]}
        merged = _normalize(spec, non_null[0])
        if len(non_null) < len(resolved):
            merged["type"] = sorted(_types(merged) | {"null"})
        return merged
    return schema


def compare_schemas(
    served_spec: Schema, served: Any, contract_spec: Schema, contract: Any, where: str
) -> list[str]:
    served = _normalize(served_spec, served)
    contract = _normalize(contract_spec, contract)
    problems: list[str] = []

    if _types(served) != _types(contract):
        problems.append(f"{where}: type {sorted(_types(served))} != {sorted(_types(contract))}")
        return problems
    if "enum" in contract or "enum" in served:
        served_enum = set(served.get("enum", [])) - PENDING_ENUM_VALUES
        if served_enum != set(contract.get("enum", [])):
            problems.append(f"{where}: enum {sorted(served_enum)} != {contract.get('enum')}")
    if served.get("format") != contract.get("format") and "format" in contract:
        problems.append(f"{where}: format {served.get('format')} != {contract['format']}")

    served_props = served.get("properties", {})
    contract_props = contract.get("properties", {})
    for name in sorted(set(served_props) - set(contract_props)):
        problems.append(f"{where}.{name}: not in the contract")
    for name in sorted(set(contract_props) - set(served_props)):
        problems.append(f"{where}.{name}: missing in the app")
    for name in sorted(set(served_props) & set(contract_props)):
        problems += compare_schemas(
            served_spec, served_props[name], contract_spec, contract_props[name], f"{where}.{name}"
        )
    missing_required = set(contract.get("required", [])) - set(served.get("required", []))
    if missing_required:
        problems.append(
            f"{where}: required in the contract but optional {sorted(missing_required)}"
        )

    if "items" in contract or "items" in served:
        problems += compare_schemas(
            served_spec,
            served.get("items", {}),
            contract_spec,
            contract.get("items", {}),
            f"{where}[]",
        )
    return problems


def _json_schema(spec: Schema, holder: Any) -> Any:
    holder = _resolve(spec, holder) or {}
    return holder.get("content", {}).get("application/json", {}).get("schema")


def _parameters(spec: Schema, operation: Schema) -> dict[tuple[str, str], Schema]:
    params = [_resolve(spec, param) for param in operation.get("parameters", [])]
    return {(param["in"], param["name"]): param for param in params}


def compare_specs(served: Schema, contract: Schema) -> list[str]:
    problems: list[str] = []
    contract_paths = contract.get("paths", {})
    for served_path, served_item in served.get("paths", {}).items():
        path = served_path.removeprefix(API_PREFIX)
        for method in HTTP_METHODS:
            if method not in served_item:
                continue
            where = f"{method.upper()} {path}"
            contract_op = contract_paths.get(path, {}).get(method)
            if contract_op is None:
                problems.append(f"{where}: operation not in the contract")
                continue
            problems += _compare_operation(
                served, served_item[method], contract, contract_op, where
            )
    return problems


def _compare_operation(
    served: Schema, served_op: Schema, contract: Schema, contract_op: Schema, where: str
) -> list[str]:
    problems: list[str] = []
    served_id, contract_id = served_op.get("operationId"), contract_op.get("operationId")
    if served_id != contract_id:
        problems.append(f"{where}: operationId {served_id} != {contract_id}")

    served_params = _parameters(served, served_op)
    contract_params = _parameters(contract, contract_op)
    if set(served_params) != set(contract_params):
        problems.append(f"{where}: parameters {sorted(served_params)} != {sorted(contract_params)}")
    for key in sorted(set(served_params) & set(contract_params)):
        problems += compare_schemas(
            served,
            served_params[key].get("schema"),
            contract,
            contract_params[key].get("schema"),
            f"{where} param {key[1]}",
        )

    served_body = _json_schema(served, served_op.get("requestBody"))
    contract_body = _json_schema(contract, contract_op.get("requestBody"))
    if (served_body is None) != (contract_body is None):
        problems.append(f"{where}: request body declared on one side only")
    elif served_body is not None:
        problems += compare_schemas(served, served_body, contract, contract_body, f"{where} body")

    contract_responses = contract_op.get("responses", {})
    for status, served_response in served_op.get("responses", {}).items():
        if status not in contract_responses:
            problems.append(f"{where}: response {status} not in the contract")
            continue
        served_schema = _json_schema(served, served_response)
        contract_schema = _json_schema(contract, contract_responses[status])
        if (served_schema is None) != (contract_schema is None):
            problems.append(f"{where} {status}: JSON body declared on one side only")
        elif served_schema is not None:
            problems += compare_schemas(
                served, served_schema, contract, contract_schema, f"{where} {status}"
            )
    return problems
